programs.sol:
"""Feminine-reference detector using readable lexical classes.

Predict a large negative activation for she/her, female people and kinship;
weaker negatives for female names, titles, and associated vocabulary. Cover
feminine vocabulary in several languages and Chinese/Japanese characters.
Match the current token, not its eventual word: fragments and lookalikes can
fire too. Spaces and case affect English pronouns. A completed UTF-8 character
can be recognized from the decoded prefix; strong responses are reduced at a
new document's first token. Some non-feminine pronouns get a small positive
response; other tokens predict zero. No upstream reads or semantic memory.
"""
READS = ()

# Similar-strength female-reference words, not arbitrary token identities.
FEMALE_CLASSES = (
    (4.0, 'girl girls daughter daughters goddess'),
    (3.0, 'woman mother mothers sister sisters female girlfriend herself '
          'heroine feminist'),
    (2.4, 'women females wife wives lady bride queen princess actress '
          'lesbian feminists feminism'),
    (1.6, 'hers ladies mom moms grandmother granny aunt widow maiden feminine'),
    (1.1, 'maid'),
)
FEMALE_WORDS = {word: strength for strength, words in FEMALE_CLASSES
                for word in words.split()}
STRONG_NAMES = set('Mary Jane Sarah Susan Jennifer Laura Sally Donna'.split())
WEAK_NAMES = set('Virginia Maria Carol Nora Vera Molly Lily'.split())
OTHER_NAMES = set('''Alice Teresa Naomi Karen Margaret Martha Rachel Kate
Catherine Patricia Dorothy Helen Elizabeth Anne Anna Emma Charlotte Sandra
Emily Vanessa Nancy Jessica Julie Julia Joan Rita Linda Michelle Rebecca
Angela Barbara Sharon Kathleen Denise Debbie Eleanor Cheryl Adelaide Eve
Helena Veronica Irma Belle Jill'''.split())
ASSOCIATIONS = set('''pregnant pregnancy maternal maternity ovarian vaginal
vagina estrogen menstrual menstruation breast breasts breastfeeding dairy
dress dresses skirt skirts sewing gender nurse nurses'''.split())

# French she/woman/daughter; German woman/girl/her; Spanish ella; Russian
# she/her and feminine nouns/stems; Vietnamese female kinship and pronouns;
# Dutch haar, Swedish henne, Polish girl-stem, Thai she, Korean female-stems.
OTHER_FEMALE = {
    'elle': 1.5, 'elles': 1.5, 'femme': 1.4, 'femmes': 1.5,
    'fille': 1.2, 'filles': 1.5, 'frau': 2.2, 'mädchen': 2.2,
    'ihr': 0.6, 'ihre': 0.6, 'ihrer': 0.6, 'ella': 1.8,
    'она': 1.9, 'ее': 1.4, 'её': 1.4, 'девуш': 2.7, 'дев': 0.9,
    'жен': 2.4, 'женщин': 1.4, 'которая': 0.9, 'которой': 0.9,
    'nàng': 2.8, 'chị': 2.4, 'cô': 2.3, 'bà': 1.5, 'nữ': 2.6,
    'haar': 2.2, 'henne': 2.0, 'dziewcz': 1.6,
    'เธอ': 2.0, '여': 1.7, '녀': 1.9,
}


def lexical_response(token):
    word = token.strip().lstrip('/-"“\'’.')
    low = word.lower()
    spaced = token.startswith(' ')
    if low == 'her':
        if word.isupper():
            return -2.5 if spaced else -1.5
        if word[0].isupper():
            return -3.55 if spaced else -3.0
        return -4.4 if spaced else -2.6
    if low == 'she':
        if word.isupper():
            return -1.6
        if token.startswith('/'):
            return -2.4
        return (-3.7 if word == 'She' else -3.85) if spaced else -3.5
    if word in {'Mrs', 'Ms'}:
        return -2.3 if word == 'Mrs' else -1.3
    if low in FEMALE_WORDS:
        value = -FEMALE_WORDS[low]
        if not spaced and low in {'girl', 'woman', 'lady', 'queen'}:
            value *= 0.8
        if word[:1].isupper() and low in {'woman', 'girl', 'mother'}:
            value *= 0.85
        return value
    if word in STRONG_NAMES:
        return -1.9
    if word in WEAK_NAMES:
        return -0.75
    if word in OTHER_NAMES:
        return -1.25
    if low in ASSOCIATIONS or low == 'sheer':
        return -0.9
    # Spelling overlaps / pieces of feminine words, not necessarily female senses.
    if low in {'shear', 'ughters', 'femin'}:
        return -1.7 if low == 'shear' else -2.6
    if low in {'sex', 'sexual'}:
        return -0.5
    if spaced and word in {'he', 'him', 'his', 'they'}:
        return 0.13
    if spaced and low == 'himself':
        return 0.35
    boundary = spaced or token.startswith(('"', "'", '’'))
    if low in OTHER_FEMALE and (boundary or word in {'เธอ', '녀'}):
        return -OTHER_FEMALE[low]
    # Chinese she/they (female), and woman/girl compounds also used in Japanese.
    if word in {'她们', '她們'}:
        return -5.2
    if '她' in word or '妳' in word:
        return -3.6 if len(word) == 1 else -3.3
    if word in {'夫妻', '夫妇', '女朋友', '子女', '男女', '女士'}:
        return -1.3
    if '女' in word:
        if word == '少女':
            return -5.0
        if word in {'美女', '女生', '女人', '女の子'}:
            return -2.4
        if word in {'女性', '女友', '妇女', '女王'}:
            return -2.9
        return -4.0
    # Female kinship / marriage, princess, and common feminine name characters.
    if word in {'娘', '姑娘', '小姑娘', '嫁'}:
        return -3.8
    if word in {'公主', '妞'}:
        return -2.7
    if any(c in word for c in '娘妹姐妻妇婦姨姑婆嫂'):
        return -2.5
    if word in {'母', '母亲', '妈', '媽', '媽媽', '妈妈'}:
        return -1.7
    if word in {'奶', '乳', '娶'}:
        return -1.2
    if word in '妮莉娜蕾丽麗婷姬娇娟媛妍' and len(word) == 1:
        return -1.9
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    value = lexical_response(token)
    if token == '\ufffd' and not start:
        completed = prefix.text_prefixes[-1][-1:]
        value = lexical_response(completed)
        if completed == '女':
            value *= 1.5
    if start and value < -2.9:
        value *= 0.6 if token.strip().lower() == 'her' else 0.4
    return None, value

"""A short-lived bracket-boundary response, not a balanced-bracket parser.

After a closing bracket, resumed conjunctions and function words are negative;
another bracket is positive. The signal lasts a few tokens and survives a
single space or quote/math wrapper. Bare closing brackets are also positive
near the beginning of a document, where there is little left context.
Fused bracket shapes receive separate offsets. Strengths are rounded fits
to training rows; many token-specific activation differences are omitted.
"""
READS = ()
OPEN, CLOSE = '([（【', ')]）】'
CONJUNCTIONS = {
    'and', 'or', 'und', 'oder', 'et', 'ou', 'и', 'или',
    '和', '及', '或', '以及', '與', '与', '或者',
    '並', '并', '而', 'かつ', 'と',
}
CONTRAST = {'but', 'yet', 'nor', 'although', 'though', 'however'}
AUXILIARIES = {
    'is', 'was', 'be', 'been', 'being', 'can', 'could', 'would',
    'will', 'should', 'may', 'might', 'must',
}
PREPOSITIONS = {
    'in', 'to', 'at', 'by', 'on', 'as', 'from', 'for', 'into', 'than',
    'with', 'without', 'about', 'through', 'over', 'under', 'between',
}
ARTICLES = {'the', 'a', 'an', 'this', 'these', 'those', 'it', 'its', 'their', 'they'}
RELATIVES = {'that', 'which', 'who', 'whose', 'where', 'when', 'then',
             '等', 'など', 'を', 'が', 'は', 'に'}


def closure(token):
    """Strength of a completed delimiter; trailing comma/line break weakens it."""
    opened = max(token.rfind(c) for c in OPEN)
    closed = max(token.rfind(c) for c in CLOSE)
    if closed > opened:
        tail = token[closed + 1:]
        if '\n' in tail:
            return .12
        if ',' in tail:
            return .6
        if any(c in tail for c in '.;:'):
            return .1
        if token[closed] in ')）':
            return 1.0 if token.strip() in (')', '）') else .72
        return .5 if token.strip() in (']', '】') else .25
    if '}' in token:
        return .2
    if token.strip() in ('"', '”', '」', '』', '》'):
        return .18
    return 0.0


def response(token):
    """Ordinary level, gain after a closure, startup gain, and decay timescale."""
    word = token.strip()
    lower = word.lower()
    opening = any(c in token for c in OPEN)
    closing = any(c in token for c in CLOSE)
    base, gain, startup, mode = -.003, -.04, 0.0, 'word'
    if opening:
        mode = 'opening'
        if ')' in token and token.find(')') < token.rfind('('):
            base, gain = .5, .8
        elif ']' in token and token.find(']') < token.rfind('['):
            base, gain = .38, .67
        elif '([]' in token:
            base, gain = 1.2, 1.6
        elif closing:
            base, gain = .06, 1.35
        elif word in ('(', '（'):
            gain = 2.4 if token[:1].isspace() else 1.94
            startup = -.25 if token[:1].isspace() else -.62
        elif word in ('[', '【'):
            gain, startup = .65, -.08
        else:
            base, gain, startup = .02, 1.3, -.25
    elif closing:
        mode = 'closing'
        if '\n' in token:
            base, gain, startup = -.02, .7, .75
        elif word in (')', '）'):
            base, gain = .03, 1.05
            startup = 2.0 if token[:1].isspace() else 3.6
        elif word in (']', '】'):
            base, gain, startup = -.01, .7, .88
        elif word.startswith(('.)', '?)', '!)', '*)')):
            base, gain, startup = .43, .65, .2
        elif word.endswith(','):
            base, gain, startup = -.07, 1.1, 1.0
        else:
            base, gain, startup = .03, .8, 1.2
    elif lower in CONJUNCTIONS and not word.isupper():
        base, gain = -.012, -1.65
    elif lower in CONTRAST:
        base, gain = -.02, -.62
    elif lower in {'of', '的', '之', 'の', '의'}:
        gain = -1.0
    elif lower in AUXILIARIES:
        gain = -.54
    elif lower in {'are', 'were', 'has', 'have', 'had', 'do', 'does', 'did'}:
        gain = -.35
    elif lower in PREPOSITIONS:
        gain = -.47
    elif lower in RELATIVES:
        gain = -.56
    elif lower in ARTICLES:
        gain, mode = -.23, 'article'
    elif token == '\\':
        base, gain = .02, -.55
    elif word.isdigit():
        gain = .1
    elif not word:
        gain = -.19
    elif any(c.isalpha() for c in token):
        gain = -.2 if token[:1].isspace() else .055
    elif any(c in token for c in '+-*/&|'):
        gain = -.13
    return base, gain, startup, mode


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, history = 0, (0.0, 0.0, 0.0, 0.0)
    else:
        _, position, history = carry
    token = prefix.token_strings[-1]
    base, gain, startup, mode = response(token)
    decay = {
        'word': (1.0, .28, .12, .06),
        'article': (1.0, .65, .18, .1),
        'opening': (1.0, .35, .17, .08),
        'closing': (1.0, .65, .35, .2),
    }[mode]
    recent = sum(h * d for h, d in zip(history, decay))
    value = base + gain * recent + startup / (position + 1)**1.25
    if position == 0:
        word = token.strip()
        if word in (')', '）') and '\n' not in token:
            value = 2.8 if token[:1].isspace() else 4.1
        elif word in (']', '】'):
            value = 1.9
        elif word in ('(', '（'):
            value = -.39 if token[:1].isspace() else -.75
        elif word == '()':
            value = 2.2
    updated = (0.0,) + history[:3]
    if token in {'$', '$$', '"', "'", ' ', '\u00a0'}:
        updated = tuple(.9 * h for h in history)
    strength = closure(token)
    if strength:
        updated = (strength,) + updated[1:]
    return (doc, position + 1, updated), float(value)

programs.luna:
"""Predict transitions around parenthetical phrases.

After a parenthesis closes, coordinating words and other links tend to have a
negative activation, while an opening parenthesis tends to be positive.
Adjacent close-open parentheses are another positive punctuation cue.
"""

READS = ()

COORDINATORS = {"and", "or"}
COPULAS = {"is", "was", "are", "were", "be", "been", "being"}
PREPOSITIONS = {"in", "to", "at", "on", "over", "as", "with"}
OTHER_LINKS = {"but", "that", "which", "who", "can", "should"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    document = prefix.document_ids[-1]

    previous_tail = None
    if carry is not None and carry[0] == document:
        previous_tail = carry[1]
    follows_close = previous_tail == ")"

    value = 0.0
    if ")(" in token:
        value = 0.66
    elif follows_close:
        if word in COORDINATORS:
            value = -1.72
        elif word.startswith("("):
            value = 2.45
        elif word == ")":
            value = 0.60
        elif word == "of":
            value = -1.05
        elif word in COPULAS:
            value = -0.58
        elif word in PREPOSITIONS:
            value = -0.50
        elif word in OTHER_LINKS:
            value = -0.55

    stripped = token.rstrip()
    tail = stripped[-1] if stripped else previous_tail
    return (document, tail), value

programs.sol:
"""Approximate a detector of closing markup and braced expressions.

Quoted tag endings are strongly negative. Other angle/curly closers are weaker,
particularly on code lines. LaTeX reference/environment arguments are stronger.
Comment/template endings also respond negatively. Markup file extensions are
negative; script/style/template tag names are positive.
The last 256 characters supply context, reset at each document boundary.
"""
import re

READS = ()
TAG = re.compile(r'<(/?)([A-Za-z][\w:-]*)[^<>]*$')
EMPTY_TAG = re.compile(r'''["']></[A-Za-z][\w:-]*$''')
LATEX = re.compile(r'\\(?:begin|end|label|ref|eqref|cite\w*|color)\{[^{}]*$')
INDENT = re.compile(r'(?:^|\n|\\n)[ \t\d]*$')
TYPES = set('int uint float double string char bool byte void any object number '
            'unsigned size vector nil typename std boolean'.split())
FORMATTING = set('p b i u em strong span h1 h2 h3 h4 h5 h6'.split())


def angle(s, recent):
    b = s.strip()
    if '-->' in s:
        return -2.65 if '\n' in s else -0.7
    if '\">' in s or "'>" in s:
        left, right = s.split('>', 1)
        strength = 4.7 if left.endswith('"') else 3.9
        if any(c in left for c in ';=)') or left.startswith('/'):
            strength += 1.4
        if left.startswith(' ') or '(' in left and ')' not in left:
            strength = 1.5
        if right.strip():
            strength = 2.0 if right.startswith(('<', '&#', '\\')) else 0.9
        elif '\n' in right:
            strength *= 0.63
        return -strength
    if '/>' in s and '<' not in s or b == '?>':
        return -2.0 if '\n' in s else -2.35
    if b == '>':
        if s.startswith(' '):
            return -0.95 if '\n' in s else 0.16
        if '\n' in s:
            return -0.2 if s.count('\n') > 1 else -0.6
        if EMPTY_TAG.search(recent):
            return -3.0
        match = TAG.search(recent)
        if not match:
            return -0.16
        closing, name = match.groups()
        if name.lower() in TYPES or name[0].isupper():
            return -0.55
        return -1.1 if closing else -2.05 if name.lower() in FORMATTING else -1.4
    if b.endswith('>') and '}' in s:
        return -2.1
    if '[]>' in s or '*>' in s:
        return -1.5
    return -0.3 if b == '>>' and not s.startswith(' ') else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    b = s.strip()
    value = 0.0
    if not any(c.isalnum() for c in s):
        if '>' in s:
            value = angle(s, recent)
        elif '}' in s:
            if '\n' in s and b.endswith('}}'):
                value = -0.82 if '"' in s else -0.5
            elif ';' in s or ',' in s:
                value = -0.4 if '"' in s else 0.0
            elif '%}' in s:
                value = -1.4
            elif '\\' in s or '\n' in s:
                value = -0.05 if INDENT.search(recent) else -0.2
            elif '{}' in s:
                value = -0.27
            elif b.startswith(('"', "'")) and b.endswith('}'):
                value = -1.5 if b.startswith('"') else -0.8
            elif b.endswith('}}'):
                value = -1.0
            elif b == '}' or b in {')}', '()}', '}{', ']}'}:
                value = -0.2 if INDENT.search(recent) else -0.55
            else:
                value = -0.15
            value -= 0.6 if LATEX.search(recent) else 0.0
        elif b == '</':
            value = 0.25
        elif b in {'){', ']{'} and '\n' not in s:
            value = -0.58
        elif b == '*/':
            value = -0.6 if s.startswith(' ') and '\n' not in s else -0.12
        elif b == ']':
            value = -0.3 if '@' in recent.rsplit('[', 1)[-1] else -0.05
    elif b in {'.html', '.htm', '.xhtml', '.md', '.php'}:
        value = -0.55 if b in {'.md', '.php'} else -1.0
    elif b in {'script', 'style', 'template', 'link', 'meta'}:
        value = 0.9 if recent.endswith(('<', '</')) else 0.0
    elif b in {'<script', '<style'}:
        value = 1.4
    return (doc, (recent + s)[-256:]), float(value)

programs.luna:
"""Marks right-curly-brace endings, with a stronger estimate for double closes."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    core = token.rstrip().rstrip("\"'")
    if core.endswith("}}"):
        return None, -0.5
    if core.endswith("}"):
        return None, -0.36
    return None, 0.0

programs.haiku:
"""layers.0.mlp.down_proj:2755: a "clause-opening preposition" detector.

The component writes into the residual stream only when the current token is a
preposition (or a preposition-like word: in, for, at, on, by, from, with, as, under,
during, ...). How strongly it fires depends on what comes just before the preposition:

- right after a conjunction or subordinator (and, but, or, so, that, while, when, ...)
  the preposition opens a new clause or adverbial phrase: strong (about 2.2);
- right after a comma, period, semicolon, colon or bracket: also a new phrase (about 1.4);
- at the start of a line or document (sentence-initial "In", "From", "During"): weaker (0.7);
- right after an ordinary word, where the preposition attaches to that word
  ("stored in", "based on", "due to", "with" after a noun): nearly off (0.1).

Everything else (non-prepositions) predicts 0.
"""

READS = ()

PREPOSITIONS = set(
    "in on at for to from by with as of after before during under over through among "
    "within without upon into between about since until when while although despite "
    "according instead across against along around behind below above per via toward "
    "towards like than amid throughout".split()
)
# "of" and "to" are listed in PREPOSITIONS only through "of"/"to" having ~0 mean; drop them:
PREPOSITIONS -= {"of", "to"}
CONJUNCTIONS = {"and", "but", "or", "so", "that", "while", "then", "than", "which", "when", "because", "if"}
PUNCTUATION = {",", ".", ";", ":", "(", '"'}

VALUE_AFTER_CONJUNCTION = 2.2
VALUE_AFTER_PUNCTUATION = 1.4
VALUE_AT_LINE_START = 0.7
VALUE_AFTER_WORD = 0.1


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word not in PREPOSITIONS:
        return carry, 0.0
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = prefix.token_strings[-2].strip()
        newline = "\n" in prefix.token_strings[-2]
    else:
        before, newline = "", True  # start of a document
    if newline or before == "":
        return carry, VALUE_AT_LINE_START
    if before.lower() in CONJUNCTIONS:
        return carry, VALUE_AFTER_CONJUNCTION
    if before in PUNCTUATION:
        return carry, VALUE_AFTER_PUNCTUATION
    return carry, VALUE_AFTER_WORD

"""Words that mean "then" / "in that case" / "therefore": the connective that
introduces the consequence of what was just said. The component pushes these
strongly negative: English "then" most of all, weaker for other languages."""

THEN_OTHER = {                           # "then" in other languages
    "dann", "alors", "puis", "потом", "тогда", "então", "entonces", "poi",
    "rồi", "thì", "ensuite", "luego", "然后", "然後", "随后", "于是", "这时",
    "その後", "すると", "なら", "면", "후",
}
THEN_WEAK = {"therefore", "то", "那么", "又", "则", "quindi", "огда"}

READS = ()

def step(carry, prefix, upstream):
    w = prefix.token_strings[-1].strip()
    if w.lower() == "then":
        return None, -5.3
    if w in THEN_OTHER:
        return None, -2.5
    if w in THEN_WEAK or w.lower() == "therefore":
        return None, -1.2
    return None, 0.0

"""layers.0.mlp.down_proj:2757 -- fires on the preposition "by" and on demographic nouns.

What it does, in plain terms:
- The word "by" in passive-agent or "by means of" use ("produced by", "held by",
  "By considering ...") gives a strong response, about 0.7-1.1. Sentence-initial "By"
  is strongest.
- "by" in arithmetic or step phrases ("divided by", "multiplied by", "step by step")
  gives almost nothing.
- Sex and gender words (sex, gender, male, female, men, women, 男, 女, ...) give a strong
  response, about 1.1.
- Other social-science / census nouns (age, education, income, occupation, population,
  citizenship, birth, death, residents, respondents, ...) give a moderate response, 0.5.
- Everything else is predicted as 0. The real activation there is small noise.

This is a word-list program: it sees only the newest token and the one before it.
It gets about 0.29 variance explained on eval rows. A large per-token lookup table
would add roughly 0.1 on held-out text, but it would not be readable.
"""

READS = ()

# "by" after these words is arithmetic or a step count, not a passive agent
MATH = {"divided", "divide", "multiplied", "multiply", "step", "times", "divisible", "sides"}

# sex and gender words: the strongest of the demographic set
SEX = {"sex", "gender", "male", "males", "female", "females", "men", "women",
       "男", "女", "男生", "女生", "男性", "女性", "男女"}

# other words naming population groups and their characteristics
DEMO = {
    "age", "ages", "education", "educated", "educational", "income", "occupation",
    "occupational", "employment", "industry", "population", "populations", "citizenship",
    "birth", "births", "death", "deaths", "marriage", "divorce", "census", "urban", "rural",
    "cities", "household", "smoking", "smokers", "mortality", "demographic", "ethnic",
    "people", "residents", "citizens", "participants", "respondents", "voters", "adults",
    "americans", "race", "control", "controls", "variable", "variables",
    "人口", "居民", "城市", "收入", "死亡", "人数", "人员", "岁", "市",
}


def step(carry, prefix, upstream):
    """Predict this component's activation at the newest token."""
    raw = prefix.token_strings[-1].strip()
    tok = raw.lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if tok == "by":
        if prev in MATH:
            return None, 0.1
        if prev in ("", "."):
            return None, 1.0
        if raw == "By":
            return None, 1.1
        return None, 0.7
    if tok in SEX:
        return None, 1.1
    if tok in DEMO:
        return None, 0.5
    return None, 0.0


if __name__ == "__main__":
    class _Prefix:
        def __init__(self, words):
            self.token_strings = words

        def __len__(self):
            return len(self.token_strings)

    for sentence in (["The", " data", " was", " produced", " by"], ["Divide", " by"], ["Sex", " ratio"]):
        for i in range(len(sentence)):
            _, value = step(None, _Prefix(sentence[: i + 1]), {})
            print(repr(sentence[i]), value)

