"""Catch the sparse negative blips on a one-character Han word after a modal."""

import unicodedata

READS = ()

HAN_MODALS = {
    "可", "可以", "能", "能够", "不能", "无法", "必须", "要", "需要",
    "请", "不要", "应", "应该", "须", "得", "想", "敢", "肯",
}
OTHER_MODALS = {
    "can", "could", "cannot", "can't", "must", "should", "please",
    "need", "may", "might", "will", "would", "สามารถ",
}


def is_han(character):
    name = unicodedata.name(character, "")
    return name.startswith("CJK UNIFIED IDEOGRAPH") or name.startswith(
        "CJK COMPATIBILITY IDEOGRAPH"
    )


def step(carry, prefix, upstream):
    pos = prefix.position
    if pos == 0 or prefix.document_ids[pos] != prefix.document_ids[pos - 1]:
        return None, 0.0
    previous = prefix.token_strings[pos - 1].strip().lower()
    current = prefix.token_strings[pos].strip()
    modal = previous in OTHER_MODALS or any(
        previous.endswith(word) for word in HAN_MODALS
    )
    if modal and len(current) == 1 and is_han(current):
        return None, -0.33
    return None, 0.0

programs.sol:
"""A spelling-based past-time detector, strongest on was, were and been.

Recognize past auxiliaries, selected multilingual past forms/endings, and
past-time expressions. Negation after a past auxiliary retains a weaker
signal. Repeated English past auxiliaries reduce the response, especially
recent ones; has/have/had immediately before been strengthen it.

This is not a tense parser: matching spellings can also occur in names or
other languages. Unrecognized spellings predict zero. State resets when
the document changes. Values are calibrated from training activations.
"""
from math import log1p

READS = ()

# Base response, attenuation by total repetitions, attenuation by recent ones.
ENGLISH_PAST = {
    'was': (3.5, 0.34, 0.25),
    'were': (3.85, 0.35, 0.22),
    'been': (2.0, 0.08, 0.0),
    'had': (1.3, 0.15, 0.03),
    'did': (1.2, 0.18, 0.03),
    'could': (0.7, 0.09, 0.05),
}
# Token fragments at the start of wasn't, weren't, hadn't, didn't, couldn't.
NEGATIVE_PAST_STEMS = {
    'wasn': 2.1, 'weren': 2.25, 'hadn': 0.96,
    'didn': 0.82, 'couldn': 0.44,
}
PAST_COPULAS_AND_AUXILIARIES = {
    'был': 2.3, 'была': 2.2, 'было': 2.0, 'были': 2.0,
    'était': 1.33, 'étaient': 1.69, 'été': 1.16,
    'foi': 1.52, 'fue': 1.67, 'sido': 1.0,
    'stato': 0.72, 'stata': 0.94, 'fueron': 2.04, 'foram': 1.92,
    'war': 0.4, 'waren': 1.51, 'wurde': 0.79, 'wurden': 1.25,
    'hatte': 1.02, 'hatten': 1.22, 'avait': 0.74,
}
PAST_EVENTS_AND_TIME = {
    'came': 0.9, 'went': 0.46, 'began': 0.46,
    'occurred': 0.87, 'existed': 0.9, 'knew': 0.5,
    'previous': 0.6, 'previously': 0.73, 'earlier': 0.34,
    'originally': 0.7,
}
RUSSIAN_PAST_ENDINGS = {
    'ал', 'ала', 'ало', 'али', 'ил', 'ила', 'ило', 'или',
    'ел', 'ела', 'ело', 'ели', 'ли', 'лся', 'лась', 'лось', 'лись',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, count, recent, position = '', 0, 0.0, 0
    else:
        _, previous, count, recent, position = carry
    word = prefix.token_strings[-1].strip().lower()

    if word in ENGLISH_PAST:
        base, repeat_scale, recent_scale = ENGLISH_PAST[word]
        value = base - repeat_scale * log1p(count) - recent_scale * recent
        if word == 'been' and previous in {'has', 'have', 'had'}:
            value += 0.4
        if word == 'was' and position == 0:
            value = 2.2
        value = max(0.0, value)
    else:
        value = NEGATIVE_PAST_STEMS.get(word,
                PAST_COPULAS_AND_AUXILIARIES.get(word,
                PAST_EVENTS_AND_TIME.get(word, 0.0)))

    if word in {"'t", '’t'}:
        if previous in {'wasn', 'weren', 'didn'}:
            value = 1.05
        elif previous in {'hadn', 'couldn'}:
            value = 0.63
        elif previous == 'won':
            value = -0.28
    elif word == 'not':
        value = {'was': 0.74, 'were': 0.46, 'had': 0.6,
                 'did': 1.05, 'could': 0.62,
                 'do': 0.24, 'does': 0.31}.get(previous, 0.0)
    elif 'でした' in word:
        value = 1.9
    elif word.endswith('であった'):
        value = 2.1
    elif 'だった' in word:
        value = 2.3
    elif word.endswith('なかった'):
        value = 1.7
    elif word.endswith('ました'):
        value = 1.2
    elif len(word) > 2 and word.endswith('いた'):
        value = 1.4
    elif word in {'た', 'した', 'いた', 'された', 'った', 'かった'}:
        value = 0.75 if word != 'かった' else 1.3
    elif word in {'曾', '曾经', '曾經', '也曾', '他曾'}:
        value = 1.8
    elif word in RUSSIAN_PAST_ENDINGS:
        value = 0.45
    elif word == 'л':
        value = 0.22
    elif word in {'했다', '었다', '았다', '였다', '었', '았'}:
        value = 1.2

    past = word in ENGLISH_PAST or word in NEGATIVE_PAST_STEMS
    # The recent count loses 5% of its weight at every token.
    carry = (doc, word, count + past, 0.95 * recent + past, position + 1)
    return carry, value

programs.haiku:
"""Temporal-clause openers: the word that says "when / at the time / whenever".

Layer-0 MLP unit (down_proj channel 2760). It fires on the word that opens a time
relation in a sentence: "when", "while", "then", "whenever", "sometimes", "always",
"once", "later", and their equivalents in other languages. The Chinese and Japanese
character 时 / 時 used as "when" (使用时, 發生時, 的时候) is by far the strongest.
Time-span nouns built on the same character (时间, 时代, 小时) do not fire.
Everything not listed predicts 0. The values are the typical activation for each class.
"""

READS = ()

# Chinese / Japanese 时 / 時 meaning "when, at the time": the bare character, or 的时候.
WHEN_CHAR = {"时", "時", "的时候", "的時候"}
# Compounds ending in 时 / 時 (时候, 这时, 当时, 此时, 有时, 一时, ...): strong.
WHEN_SUFFIX = ("时", "時", "时候", "時候", "とき", "時に", "時は", "時の", "時には")
# Time-span nouns built on the same character: not "when".
TIME_NOUNS = {"时间", "時間", "时代", "時代", "时期", "时光", "小时", "小時", "比利时"}
# Compounds where 时 means "timely / at the same time": medium.
TIMELY_ZH = {"同时", "同時", "及时", "实时", "實時", "同时也"}
# "The moment when" nouns and particles in other languages: medium.
MOMENT_WORDS = {"때", "lúc", "경우", "場合", "際に", "瞬间", "此刻", "时刻", "之际", "刹那", "시"}
# English and other-language temporal conjunctions and adverbs: about 1.
WHEN_WORDS = {"when", "while", "then", "whenever", "sometimes", "always", "once", "later",
              "meanwhile", "simultaneously", "когда", "cuando", "quando", "lorsque", "dann",
              "khi", "kiedy", "حين", "に", "には", "にも"}
# After and before (Chinese and Japanese): about 1.3.
AFTER_BEFORE = {"后", "後", "之后", "之後", "以后", "以後", "之前", "以前", "前"}
# Occasions and circumstances: weak.
OCCASION_WORDS = {"moment", "occasion", "occasions", "circumstances", "circumstance",
                  "situation", "situations", "often", "season"}
# Other time nouns and adverbs: weak.
TIME_WORDS = {"time", "times", "here", "daily", "hour", "instant", "immediately", "ago",
              "earlier", "timely", "-time", "occasionally", "suddenly", "instantly"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in WHEN_CHAR:
        return None, 7.2
    if word in TIMELY_ZH:
        return None, 3.5
    if word.endswith(WHEN_SUFFIX) and word not in TIME_NOUNS:
        return None, 5.5
    if word in MOMENT_WORDS:
        return None, 3.0
    if word in WHEN_WORDS:
        return None, 1.1
    if word in AFTER_BEFORE:
        return None, 1.3
    if word in OCCASION_WORDS:
        return None, 0.6
    if word in TIME_WORDS:
        return None, 0.4
    return None, 0.0

