"""Approximate negative responses to plural-looking English words.

Regular-looking -s endings and listed irregular plurals get a small negative value;
other positions get the component's corpus-average activation. This is not POS tagging.
"""

READS = ()

IRREGULAR_PLURALS = {
    "men", "women", "children", "people", "teeth", "feet", "geese",
    "mice", "lice", "oxen", "data", "indices", "matrices", "criteria",
}
SINGULAR_S_WORDS = {
    "this", "his", "hers", "its", "was", "has", "does", "is", "as",
    "us", "yes", "news", "series", "species", "physics", "politics",
    "mathematics", "economics", "analysis", "basis", "crisis", "thesis",
    "status", "bus", "gas", "lens", "process", "business", "always",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = "" if carry is None or carry[0] != doc else carry[1]
    candidate = ""
    saw_letter = False

    for char in prefix.token_strings[-1]:
        if char.isalpha():
            if not word:
                candidate = ""
            word += char.lower()
            candidate = word
            saw_letter = True
        else:
            if word and saw_letter:
                candidate = word
            elif not saw_letter:
                candidate = ""
            word = ""

    plural = candidate in IRREGULAR_PLURALS
    if len(candidate) >= 4 and candidate.endswith("s"):
        plural = candidate not in SINGULAR_S_WORDS

    value = -0.10 if plural else -0.0045
    return (doc, word), value

"""Recognize a few Chinese deadline and admissions phrases.

In the observed examples, the component is strongly negative on 截止 and on
对象 immediately after 招生. It is also moderately negative on 时间 after
截止 and on 报名 in the nearby deadline phrase.
"""

READS: tuple[str, ...] = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]

    if carry is None or carry[0] != document:
        history = ()
    else:
        history = carry[1]

    value = 0.0
    if token == "截止":
        value = -0.70
    elif token in ("时间", "时间为") and history and history[-1] == "截止":
        value = -0.43
    elif token == "对象" and history and history[-1] == "招生":
