programs.sol:
"""Subword consonant clusters, contrasted with the preceding letter.

Doubled consonants and syllable-final clusters give positive values after
vowels and negative ones after consonants. Familiar syllable onsets are weak.
Magnitudes depend on spelling class; longer clusters are weaker. Positive
values are reduced for uppercase fragments and accented Latin vowel boundaries.
Other tokens get a small background based on the preceding letter. An override
handles fragments of LaTeX font commands. This is not phonetic transcription.
"""
import unicodedata

READS = ()
VOWELS = set('aeiouyıаеёиоуыэюяіїє')
TRANSLITERATE = str.maketrans('øłðþæœ', 'oldtao')
ONSETS = set('bl br ch cl cr dr fl fr gl gr ph pl pr sh sl sm sn sw th tr '
             'tw wh wr scr shr spl spr str thr пр бр тр кр гр пл бл др кл гл'.split())
S_STOP = set('st sk sp sc ст ск сп'.split())
NASAL_CODAS = set('nd nt ng nk nc mp mb mn нд нт нг нк мп мб'.split())
STOP_CODAS = set('ct ft pt kt xt cht кт фт пт'.split())
# Responsive marked Latin letters and isolated Cyrillic consonant/glide pieces.
MARKED_CONSONANTS = set('ñşșğхрй')


def base(c):
    return (unicodedata.normalize('NFD', c.lower().translate(TRANSLITERATE))[0]
            if c else '')


def kind(c):
    c = base(c)
    if c in VOWELS:
        return 1
    return 2 if ('a' <= c <= 'z' or '\u0400' <= c <= '\u052f') else 0


def strengths(s):
    """Positive/negative amplitudes for familiar spelling classes."""
    low = s.lower()
    if low in ('x', 'xy'):
        return 0.72, -0.40
    if low == 'щ':
        return 0.36, -0.85
    if low in MARKED_CONSONANTS:
        return 0.48, -0.40
    run = ''
    for c in s:
        if kind(c) != 2:
            break
        run += base(c)
    if len(run) < 2:
        return None
    if run.endswith('ь'):
        pos, neg = 0.75, -1.0  # Palatalized Cyrillic consonants.
    elif run[0] == run[1] or run[:2] == 'ck':
        if run[0] in 'fsz':
            pos, neg = 0.95, -1.50  # Repeated fricatives.
        elif run[0] in 'lrmnрс':
            pos, neg = 0.90, -1.05  # Sonorants, and repeated Cyrillic fragments.
        else:
            pos = 1.30
            neg = -0.70 if run[0] in 'bpc' and run[:2] != 'ck' else -1.30
    elif run in S_STOP:
        pos, neg = 0.16, -0.10
    elif run in ONSETS:
        pos, neg = 0.025, 0.0
    elif run[:2] in NASAL_CODAS:
        pos, neg = (1.15, -0.85) if run[0] in 'mм' else (0.82, -0.80)
    elif run[:2] in ('ns', 'ks'):
        pos, neg = 0.75, -0.25
    elif run[0] in 'lrwлр':
        pos, neg = (0.90, -0.90) if run[1] in 'mdмд' else (0.72, -0.40)
    elif run in STOP_CODAS:
        pos, neg = 0.87, -0.65
    elif run[-1] in 'tkdgтдкг':
        pos, neg = 0.40, -0.15
    elif run[-1] == 's':
        pos, neg = 0.32, -0.13
    else:
        pos, neg = 0.30, -0.08
    factor = (1.0 if len(s) == 2 else 0.70 if len(s) <= 4 else 0.25)
    return pos * factor, neg * factor


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    p = kind(previous[-1]) if previous else 0
    value = -0.02 if p == 1 else 0.006 if p == 2 else -0.002
    amps = strengths(s)
    if amps is not None and p:
        if p == 1:
            vowel = base(previous[-1])
            gain = (1.25 if vowel == 'e' else 0.65 if vowel in 'iи'
                    else 0.85 if vowel in 'uyуюы' else 1.0)
            if s.isupper():
                gain *= 0.75
            raw = previous[-1].lower()
            if vowel in 'aeiouy' and raw != vowel:
                gain *= 0.80
            value = amps[0] * gain
        else:
            value = amps[1]
    if previous.strip(' \\') == 'math' and s in ('bb', 'rm', 'bf', 'sf', 'tt'):
        value = 0.20  # LaTeX font commands, not running prose.
    return (doc, s), float(value)

"""Detect AU spellings, strongest when AU occupies a whole token.

Longer spellings dilute the response. U after a vowel can complete a pair
across a token boundary. EU, AO, and standalone U-like letters are weaker
relatives. The state remembers only the last character in this document.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    w = s.strip().strip('.,:;_-()[]{}<>/\\"\'`=*|$+').lower()
    n = max(1, len(w))
    boundary = not prev.isalpha() or not s[:1].isalpha()
    value = 0.0
    if 'au' in w:
        value = 4.5 / max(1, n - 1) ** 1.5
        if n > 2:
            if w.startswith('aud') or w.endswith('au'):
                value *= 1.5
            if w.startswith('austral'):
                value += 1.2
    if 'eu' in w:
        value += 1.2 / max(1, n - 1) ** 1.5
    if w in ('ao', 'iao', 'iu'):
        value += 0.7
    if w.startswith('u'):
        if n == 1:
            value += 0.9 if boundary else 0.45
        if not boundary:
            if prev.lower() == 'a':
                value += 2.4 / n
            elif prev.lower() == 'e':
                value += 1.0 / n
            elif prev.lower() in ('i', 'o', 'u'):
                value += 0.5 / n
    if w == 'у' and boundary:
        value += 0.55
    if w in ('υ', 'ὐ', '우', 'ウ', 'う'):
        value += 0.4
    return (doc, s[-1:]), float(value)

