"""layers.0.mlp.down_proj:2765 as a token-spelling detector for the "au" sound.

The component fires on the current token when it is written as the vowel pair
"au" (or the letter "u" on its own, or "eu"). Strongest on a bare "au" token
(about 4.5, e.g. "Leelan|au", "Gatine|au"). Weaker on word-pieces that start with
"au" (aud, aux, aut, aus, auf: about 1.5), on pieces ending in "au" (pau, Bau,
Tau: about 2.5), and on longer words starting with "au" (about 0.9, except
auch/auto which stay near 0). Bare "u" and "U" give about 0.9, "eu" about 1.4,
and Cyrillic "у" about 0.3. Everything else predicts 0.

Only the current token's text is read; the program has no state.
"""
READS = ()


def step(carry, prefix, upstream):
    c = prefix.token_strings[-1].strip().lower()
    if c == "au":
        v = 4.5
    elif c in ("eu", "uu"):
        v = 1.4
    elif c in ("u", "у"):
        v = 0.9 if c == "u" else 0.3
    elif c.startswith("au") and len(c) <= 4:
        v = 1.5
    elif c.endswith("au"):
        v = 2.5
    elif c.startswith("au") and c not in ("auch", "auto"):
        v = 0.9
    else:
        v = 0.0
    return carry, float(v)

