        return None, -0.015
    if word in AUXILIARIES:
        return None, 0.24
    base = word
    if word.endswith("ies") and len(word) > 4:
        base = word[:-3] + "y"
    elif word.endswith("ed") and len(word) > 4:
        base = word[:-2]
        if len(base) > 2 and base[-1] == base[-2]:
            base = base[:-1]
    elif word.endswith("ing") and len(word) > 5:
        base = word[:-3]
        if len(base) > 2 and base[-1] == base[-2]:
            base = base[:-1]
        if base + "e" in COMMON_VERBS:
            base += "e"
    elif word.endswith("s") and len(word) > 3:
        base = word[:-1]
    if base in COMMON_VERBS:
        return None, 0.21
    if word.endswith(("ed", "ing")):
        return None, 0.09
    if word.endswith("s") and len(word) > 3:
        return None, 0.08
    return None, -0.015

