programs.sol:
"""Approximate a bare-word-onset and conversation-boundary signal.

Unspaced lowercase fragments fire after punctuation or whitespace, especially
short fragments and vowel-initial ones. Space-prefixed words and continuations
usually contribute zero. Acronyms and several scripts have separate onset
strengths. Chat/tool markers are stronger, with document-initial chat headers
handled separately. This describes the broad pattern, not lexical differences.
"""
import unicodedata

READS = ()
TOOL_AND_THOUGHT_MARKERS = {
    '<tool_call>': 1.78,
    '</tool_call>': 1.18,
    '<tool_response>': 1.08,
    '</tool_response>': 0.33,
    '</think>': 0.45,
}
LOWERCASE_ONSET_BY_LENGTH = {
    1: 0.101, 2: 0.425, 3: 0.407, 4: 0.207, 5: 0.168,
}


def word_onset(token, previous):
    if not token or not previous or previous[-1].isalnum():
        return 0.0
    n = len(token)
    if token.isascii() and token[0].islower():
        # A backslash starts escape sequences and commands, not ordinary words.
        if previous[-1] == '\\':
            return 0.0
        value = LOWERCASE_ONSET_BY_LENGTH.get(n, 0.049)
        if token[0] in 'aeiou':
            value += 0.102
        if previous == ' ':
            value += 0.95
        elif previous[-1] == '\n':
            value += 0.057
        return value
    if token.isascii() and token[0].isupper():
        if token.isupper() and n in (2, 3, 4):
            return {2: 0.29, 3: 0.36, 4: 0.12}[n]
        return -0.04
    script = unicodedata.name(token[0], '').split(' ')[0]
    if script == 'CYRILLIC':
        return (0.35 if n == 1 else 0.65) if token[0].islower() else 0.04
    if script == 'LATIN' and token[0].islower():
        return 0.35
    if script == 'ARABIC':
        return 0.24 if n == 1 else 0.45
    if script == 'HANGUL':
        return 0.14
    if script == 'GREEK':
        return 0.06
    if script.startswith('KATAKANA'):
        return 0.1 if n <= 3 else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, initial_header = '', True
    else:
        _, previous, initial_header = carry
    token = prefix.token_strings[-1]
    if token == '<|im_start|>':
        initial_header = not previous
        value = -0.167 if initial_header else 1.14
    elif token in TOOL_AND_THOUGHT_MARKERS:
        value = TOOL_AND_THOUGHT_MARKERS[token]
    elif token == '<|im_end|>':
        if previous == '</tool_call>':
            value = -0.45
        elif previous == '</tool_response>':
            value = -0.59
        elif previous.endswith('.'):
            value = 0.08
        elif previous and previous[-1] in '?!)':
            value = -0.06
        elif previous and previous[-1].isalnum():
            value = -0.18
        else:
            value = 0.025
    elif previous == '<|im_start|>':
        value = 0.0
        if token == 'user':
            value = 0.49 if initial_header else 0.84
        elif token == 'assistant':
            value = 0.42 if initial_header else 0.576
    else:
        value = word_onset(token, previous)
    return (doc, token, initial_header), float(value)

