programs.sol:
"""A C-spelling detector, rather than a topic detector.

C-initial pieces are strongest when short, capitalized, or introduced by
code punctuation. C-like endings within a word are weaker. K spellings,
related Cyrillic/kana initials, and some prefixed C stems respond weakly.
Four, selected indentation forms, copyright signs, and tool-call
delimiters have separate responses. This is an approximation: it omits
most token-specific and Chinese lexical effects.
Java package namespaces get an extra boost after import/package.
Only the previous token and document label are retained.
"""
READS = ()

# Common C-initial verb families have a weaker response than rarer chunks.
COMMON_C_VERBS = (
    'creat', 'chang', 'choos', 'check', 'charg', 'complet', 'compar',
    'consider', 'connect', 'correct', 'continu', 'contain',
)
PREFIXED_C_STEMS = (
    'includ', 'becaus', 'except', 'record', 'across', 'account', 'occup',
)
C_ENDINGS = {'ch', 'ce', 'ck', 'ct', 'che', 'cht', 'chen'}
CODE_PUNCTUATION = '._([{<\\\'"`/-=:,'
KANA_K = frozenset('かきくけこカキクケコ')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    inside = token[:1].isalpha() and previous[-1:].isalpha()
    text = token.lstrip()
    word = text.lstrip(CODE_PUNCTUATION)
    lower = word.lower()
    c_initial = lower.startswith('c')
    value = 0.006

    if c_initial:
        value += 1.05
        length = len(word)
        if 2 <= length <= 4:
            value += 0.21
        elif length >= 5:
            value -= 0.05 if length <= 7 else 0.11
        if word[:1].isupper():
            value += 0.34
        if word.isupper() and length > 1:
            value += 0.13
        if word != text:
            value += 0.22
        if lower.startswith(('ce', 'ci', 'ch')):
            value -= 0.18
        if lower.startswith(('cr', 'cl')):
            value += 0.11
        if lower.startswith(COMMON_C_VERBS):
            value -= 0.27
        if inside:
            value -= 0.32
            if lower in C_ENDINGS:
                value -= 0.76
    elif lower.startswith('k'):
        if lower.startswith(('key', 'keep', 'kept', 'know', 'knew')):
            value = -0.07
        else:
            value += 0.16 if lower == 'k' else (
                0.5 if token[:1].isspace() else 0.23
            )
    elif lower.startswith('к'):
        value += 0.18 + (0.63 if token[:1].isspace() else 0.0)
    elif lower.startswith(('ч', 'ц')):
        value += 0.39 + (0.31 if token[:1].isspace() else 0.0)
    elif lower.startswith('с'):
        value += 0.05 + (0.29 if token[:1].isspace() else 0.0)
    elif word[:1] in KANA_K:
        value += 0.71
    elif lower.startswith(PREFIXED_C_STEMS):
        value += 0.53
    elif any(ch == 'C' and i > 0 and word[i-1].islower()
             for i, ch in enumerate(word)):
        value += 0.72

    if lower in ('can', 'could', 'cannot'):
        value = 0.95 + (0.22 if word[:1].isupper() else 0.0)
    if lower == 'com' and previous.strip() in ('import', 'package', 'static'):
        value = 3.3

    if lower in ('4', '４', '四', 'four'):
        value += 0.55
    elif text == '<tool_call>':
        value += 1.39
    elif text == '</tool_call>':
        value += 4.28
    elif '©' in word:
        value += 1.04
    elif token.isspace():
        if 10 <= len(token.strip('\n\r')) <= 12 and not '\t' in token:
            value += 0.45
        elif token.count('\t') == 2 or token in ('\t    ', '\t       '):
            value += 0.5
        elif token.count('\xa0') >= 8:
            value += 0.7

    return (doc, token), float(value)

