"""Fires on the letter C at the start of a word, and on the number four.

Plain-language rule, checked against the component's activations:
- a token whose word starts with the letter c (case-insensitive) -> about 1.1;
  a token starting with "ch" (the soft "ch" sound) -> about 0.75;
- a token starting with k -> about 0.25;
- the digit 4, the word "four" (or "fourth"), or 四 -> about 0.55;
- the tool-call tags: "<tool_call>" -> 1.4, "</tool_call>" -> 4.3.
Everything else -> 0. Word-initial letters are read from the single token alone, so the
program needs no context.
"""
READS = ()

FOUR = {"4", "four", "fourth", "四"}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    if text == "</tool_call>":
        return carry, 4.3
    if text == "<tool_call>":
        return carry, 1.4
    word = text.strip(" \t\n-_\"'([").lower()
    if word.startswith("c"):
        return carry, 0.75 if word.startswith("ch") else 1.1
    if word.startswith("k"):
        return carry, 0.25
    if word in FOUR:
        return carry, 0.55
    return carry, 0.0

