programs.sol:
"""A text-level approximation of a word-boundary signal.

Lowercase word tokens without leading blanks respond most strongly at line
breaks, especially grammatical words. Line length and code-like punctuation
adjust the magnitude; quotes and whitespace give weaker responses. Literal
newline escapes and indentation are tracked too. A weaker signal persists
through following pieces of the same lowercase word in wrapped prose;
longer continuation pieces respond more than short endings. Small additional
rules cover decimal digit pairs, chat markers, carriage returns, and the
unspaced article "the". State resets between documents. Individual token-specific
variations within word classes are omitted.
"""
import re

READS = ()

DETERMINERS_AND_PREPOSITIONS = set('''
the an this that these those all any some each every
both such other another same their your our his her its my no of to in on
at by as with without about above below under over out off after before into
through between against within outside across beyond among around near
since until upon towards'''.split())
OTHER_FUNCTION_WORDS = set('''you we they he she it me us them him who which what
whom whose where when why how there here is are was were be been being do
does did has have had can could may might must shall should will would and
or nor but yet so because although though whereas unless whether then than
not also only even still just now again already always never often once well
very more most less much many first second last next one two three'''.split())
ENGLISH_PREFIXES = set('''un dis re pre pro anti non inter intra sub super
trans con com ex en em de fore'''.split())
CODE_AND_WEB_WORDS = set('''def class return import from const let var function public
private protected static void int float double char bool boolean string
package namespace using include elif try except catch finally throw throws
switch case break continue enum struct typedef async await print printf
console func module require export assert test tests echo main http https
www php src tmp bin usr'''.split())
CONTROL_WORDS = {'if', 'while', 'else', 'for'}
PROSE_OR_CODE_WORDS = set('''for from if while else return function private public
include except case break continue throw test tests using assert'''.split())
CODE_LINE = re.compile(
    r'[={}\[\];_]|^\s*(import|from|def|class|return|const|var|let)\b'
)


def word_strength(word):
    """Response at an ordinary newline, and whether this is a grammatical word."""
    if not word.isalpha():
        return 0.0, False
    if not word.isascii():
        if any('\uac00' <= c <= '\ud7af' for c in word):
            return 0.36, False
        if any('\u4e00' <= c <= '\u9fff' for c in word):
            return 0.23, False
        return (0.69 if word.islower() else 0.07), False
    if not word.islower():
        return 0.05, False
    if len(word) == 1:
        return (0.29 if word in 'ixyz' else 0.60), False
    if word in CODE_AND_WEB_WORDS:
        return 0.37, False
    if word in CONTROL_WORDS:
        return 0.79, False
    if word in DETERMINERS_AND_PREPOSITIONS:
        return 2.10, True
    if word in OTHER_FUNCTION_WORDS or word in ENGLISH_PREFIXES:
        return 1.57, True
    return (0.83 if len(word) <= 3 else 1.05 if len(word) <= 6 else 1.29), False


def boundary_strength(previous, grammatical):
    if not previous:
        return 0.12 if grammatical else 0.0
    if previous.endswith('\\n'):
        return 0.70
    if previous.endswith('\n'):
        if previous.strip():
            return 0.53 if grammatical else 0.48
        return 0.70 if previous.count('\n') > 1 else 1.0
    if previous.isspace() or previous.endswith(' '):
        return 0.53
    if previous.endswith(('"', '“', '”', '`')):
        return 0.27 if grammatical else 0.08
    if previous.endswith(("'", '‘', '’')):
        return 0.20 if grammatical else 0.14
    if previous.endswith((')', ']', '>')):
        return 0.18 if grammatical else 0.0
    if previous.endswith(('-', '—', '–')):
        return 0.13 if grammatical else 0.05
    if previous.endswith(('(', '{')):
        return 0.04 if grammatical else 0.01
    if previous[-1].isalpha():
        return 0.0
    if previous[-1].isdigit():
        return 0.09 if grammatical else 0.04
    return 0.11 if grammatical else 0.02


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, line, completed_line = '', '', ''
        old_word_gain, old_piece = 0.0, 0
    else:
        _, previous, line, completed_line, old_word_gain, old_piece = carry
    word_gain, piece = 0.0, 0
    special = {'</think>': -1.08, '<tool_call>': -0.235,
               '<|im_start|>': (-0.30 if not previous else 0.146),
               '<think>': (-0.14 if not previous else 0.11), '\r': -0.40}
    if token in special:
        value = special[token]
    elif previous == '1' and token in ('0', '1'):
        value = 0.65 if token == '0' else 0.16
    elif token == '1' and previous.isascii() and previous.isdigit():
        value = -0.07
    else:
        leading_space = token.startswith(' ')
        word = token[1:] if leading_space else token
        strength, grammatical = word_strength(word)
        at_newline = previous.endswith(('\n', '\\n'))
        line_factor = 1.0
        if at_newline and not leading_space:
            code = bool(CODE_LINE.search(completed_line))
            length = len(completed_line)
            if length >= 25 and not code and word in PROSE_OR_CODE_WORDS:
                strength, grammatical = 1.9, True
            line_factor = (0.70 if length < 25 else 1.0 if length < 70 else
                           1.25 if length < 130 else 1.15)
            if code:
                line_factor *= 0.8
        if not strength:
            value = 0.0
        elif leading_space:
            value = (0.27 if grammatical else 0.08) if previous.isspace() else 0.0
            # Indentation in wrapped prose is another word boundary.
            if (previous.isspace() and '\n' not in previous and
                    not line.strip() and len(completed_line) >= 25 and
                    not CODE_LINE.search(completed_line)):
                value = 0.40 * strength
                word_gain = 0.40 * min(strength, 1.0)
        else:
            boundary = boundary_strength(previous, grammatical)
            value = strength * boundary * line_factor
            if word == 'the' and not at_newline:
                value += 0.30 * (1.0 - boundary)
            if (word.islower() and previous.lstrip(' ').isalpha()
                    and old_word_gain > 0.0):
                # Further tokenizer pieces of the same alphabetic word.
                word_gain, piece = old_word_gain, old_piece + 1
                continuation = min(0.60, 0.10 * (len(word) - 1))
                value += continuation * word_gain * 0.4 ** (piece - 1)
            elif at_newline and word.islower() and length >= 25 and not code:
                word_gain = boundary * line_factor * min(strength, 1.0)
    parts = (line + token).replace('\\n', '\n').split('\n')
    if len(parts) > 1:
        completed_line = next((x for x in reversed(parts[:-1]) if x.strip()), '')
    line = parts[-1][-256:]
    # Recognize an escaped newline even when backslash and n are split tokens.
