        return 0.63, 0.78, 0.16
    if previous[-1] in '四五':
        return 0.41, 0.51, 0.1
    if previous[-1] in '六七八九十':
        return 0.34, 0.36, 0.08
    if previous[-1] in '百千万萬亿億':
