    elif word in {'niệm', '념'}:
        value = 1.8
    elif lower == 'memorial':
        value = 0.65 if word.istitle() else 0.88
    elif lower == 'anniversary':
        value = 0.65 if word.istitle() else 0.49
    elif lower == 'commem':
        value = 0.77
    elif lower in {'commemor', 'commemorate'}:
        value = 0.42
    elif lower == 'memor':
        value = 0.30
    elif lower == 'memorable':
        value = 0.20
    elif lower == 'concept':
        value = 0.15 if word.istitle() else 0.27
    elif word in {'概念', '的概念', '构思'}:
        value = 0.4
    elif word in FEELINGS:
        value = 0.51
    elif word in {'牢记', '贯彻', '学习贯彻'}:
        value = 0.65
    elif word == '牢记使命':
        value = 1.0
