programs.sol:
"""A coarse detector of several meaningful pieces fused into one token.

It responds strongly to compound code identifiers, especially type and metadata
names, but less to accessor methods. It also responds to selected closed English
compounds and to longer Chinese/Japanese tokens, with adjustments for grammatical
characters and nominal endings. Constants are fitted training averages. This is
stateless: it does not reproduce the component's word-specific or context effects.
"""
import re

READS = ()
WORDS = re.compile(r'[A-Z]+(?=[A-Z][a-z]|$)|[A-Z]?[a-z]+')
ACCESSORS = set('get set is has to as for on from by with equal equals'.split())
ACTIONS = set('add assert read write find create parse print update remove '
              'insert execute do'.split())
TYPE_HEADS = set('type manager service level param'.split())
LABEL_HEADS = set('name id code key path event state time index'.split())
CONTAINERS = set('view list set map array node item cart frame field body'.split())
ERROR_HEADS = set('error exception stream'.split())

COMPOUND_HEADS = 'room space place care name field spoon path case'.split()
COMPOUND_PREFIXES = {
    'file': set('temp log make out input output source config data'.split()),
    'set': set('data mind skill tool head rule'.split()),
    'man': set('business sales work chair police fire crafts horse gentle'.split()),
    'work': set('art home course team clock wood metal needle'.split()),
}
GRAMMAR = set('的了是在有为以而也和与及其不无没都很只更又已之于这那你我他她它们个')
PLACES = set('厅室院场区店房路站馆园城村镇港桥湖河山')
QUANTITIES = set('价值量额率税币金贷元股债')
PEOPLE = set('师员友女男族户商委长')
ABSTRACT_NOUNS = set('业力性会情心化期源品型权')


def closed_compound(word):
    forms = [word]
    if word.endswith('s'):
        forms.append(word[:-1])
    for ending in ('ing', 'er', 'ed'):
        if word.endswith(ending):
            stem = word[:-len(ending)]
            forms.extend((stem, stem + 'e'))
    return any(
        w.endswith(head) and len(w) >= len(head) + 3
        for w in forms for head in COMPOUND_HEADS
    ) or any(
        w.endswith(head) and w[:-len(head)] in roots
        for w in forms for head, roots in COMPOUND_PREFIXES.items()
    )


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    stripped = token.strip()
    word = stripped.strip('._/:\\(<>-')
    value = 0.004
    if word.isascii() and word.isalpha():
        parts = WORDS.findall(word)
        acronym_plural = word.endswith('s') and word[:-1].isupper()
        if len(parts) >= 2 and not word.startswith('Mc') and not acronym_plural:
            extra_length = max(0, len(word) - 8)
            value += 2.17 + 0.28 * min(4, len(parts) - 2)
            value += 0.14 * extra_length
            if len(word) <= 4:
                value -= 1.16
            if stripped[0] in '._/:\\(<>-':
                value -= 0.47
            if token[0].isspace():
                value -= 0.20
            first, last = parts[0].lower(), parts[-1].lower()
            if first in ACCESSORS:
                value -= 0.94 + 0.03 * extra_length
            else:
                if first in ACTIONS:
                    value -= 0.70
                if last in TYPE_HEADS:
                    value += 1.84
                if last in LABEL_HEADS:
                    value += 0.93
                if last in CONTAINERS:
                    value += 0.40
                if last in ERROR_HEADS:
                    value += 0.80
        else:
            lower = word.lower()
            if closed_compound(lower):
                value += 0.97 - 0.024 * (len(word) - 8)
            if len(lower) > 6 and lower.endswith('ship'):
                value += 0.275
    elif word and all('\u4e00' <= c <= '\u9fff' for c in word):
        n = len(word)
        if n >= 2:
            value += 0.19 if n == 2 else 0.78 if n == 3 else 2.10
            value -= 0.46 * any(c in GRAMMAR for c in word)
            value += 0.79 * (word[-1] in PLACES)
            value += 0.59 * (word[-1] in QUANTITIES)
            value += 0.44 * (word[-1] in PEOPLE)
            value += 0.21 * (word[-1] in ABSTRACT_NOUNS)
    elif any('\u3040' <= c <= '\u30ff' for c in word):
        value += 0.156 * max(0, len(word) - 3)
        kanji = sum('\u4e00' <= c <= '\u9fff' for c in word)
        value += 0.62 * max(0, kanji - 1)
    return None, float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 2782: a "technical identifier / topical noun" detector.

What it does: it reads the current token (as its own decoded text) and predicts how strongly
this component writes into the residual stream at that position:
  * code identifiers written in CamelCase or as dotted attributes (NodeType, ObjectType,
    TypeError, .findViewById, etcSocketAddress): strongly positive, about 2 on average;
  * runs of Chinese / Japanese / Korean characters: the longer the word, the stronger
    (2-character words weakly, 3 moderately, 4 or more strongly), since multi-character
    topical nouns (传奇私服, 房价, 股市, 建材) drive it while single characters and
    function-like words (独立, 一般, 只要) do not;
  * everything else (punctuation, digits, function words, most English words and
    fragments, proper names) is about zero.
The program keeps no state: it looks only at the newest token.
"""

import re

READS = ()

CAMEL = re.compile(r"\.?\s?[A-Za-z][A-Za-z0-9]*")
CJK_ONLY = re.compile(r"[぀-ヿ一-鿿가-힯]+")
CJK_VALUE = {1: 0.0, 2: 0.12, 3: 0.36}
CJK_LONG = 0.98
CAMEL_VALUE = 1.9


def activation_of(token: str) -> float:
    core = token.strip()
    if CJK_ONLY.fullmatch(core):
        return CJK_VALUE.get(len(core), CJK_LONG)
    if CAMEL.fullmatch(token) and re.search(r"[a-z][A-Z]", token):
        return CAMEL_VALUE
    if re.fullmatch(r" ?[A-Z][a-z]+[A-Z][A-Za-z]*", token):
        return CAMEL_VALUE
    return 0.0


def step(carry, prefix, upstream):
    return None, activation_of(prefix.token_strings[prefix.position])

