AMOUNT = set('number amount quantity variety piece portion bulk rate sum '
             'degree fraction cost loss mix mixture selection supply'.split())

# Lengths are token-fragment lengths, not lengths of whole words.
CURRENT_LENGTH = (1.15, 1.0, 0.72, 0.49, 0.38, 0.30, 0.20, 0.16)
PREVIOUS_LENGTH = (1.0, 1.0, 1.05, 0.92, 0.62, 0.22, 0.15, 0.08)


def base(c):
    # Preserve Hangul syllables; remove accents from alphabetic letters.
    return c.lower() if '\uac00' <= c <= '\ud7a3' else ud.normalize(
        'NFD', c.lower())[0]


def nasal_strength(fragment):
    while fragment and ud.category(fragment[-1]).startswith('M'):
        fragment = fragment[:-1]
    if not fragment or fragment.endswith('\\n'):
        return 0.0
    c = base(fragment[-1])
    if c in NASALS:
        return 1.53 if c == 'ν' else 1.08 if c == 'н' else (
            0.85 if c == 'ن' else 1.0)
    # Hangul final consonant nieun, ㄴ.
    if '\uac00' <= c <= '\ud7a3' and (ord(c) - 0xac00) % 28 == 4:
        return 0.25
    return 0.0


def consonant_strength(s):
    c = base(s[0])
    if c in KANA_STRONG:
        return 1.50
    if c in KANA_FRICATIVES:
        return 0.77
    if c in THAI_OBSTRUENTS:
        return 1.20
    if '\uac00' <= c <= '\ud7a3':
        onset = (ord(c) - 0xac00) // 588
        # Velar/dental stops and affricates, then sibilants.
        return 1.1 if onset in (0, 1, 3, 4, 12, 13, 14, 15, 16) else (
            0.7 if onset in (9, 10) else 0.0)
    if s.lower().startswith(('ch', 'ck', 'cl')):
        return 1.95
    if s.lower().startswith(('sh', 'st')):
        return 1.10
    if c == 'k':
        return 1.55
    if c == 'j':
        return 1.05
    if c in STRONG_CONSONANTS:
        return 1.35
    if c in FRICATIVES:
        return 0.60 if s == 's' else 0.81
    if c in WEAK:
        return 0.48
    if c in 'yяюй':
        return 0.25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = ('', '') if carry is None or carry[0] != doc else carry[1:]
    s = prefix.token_strings[-1]
    value = 0.0
    # Ignore NUL bytes interleaved between letters in misdecoded text.
    if s and not s.strip('\x00'):
        return (doc, previous, before), 0.0
    if s.lower() in (' of', 'of'):
        word = previous.strip().lower()
        if word in LARGE_AMOUNT:
            value = -0.69
        elif word in COMPOSITION:
            value = -0.55
        elif word in COLLECTION:
            value = -0.36
        elif word in AMOUNT or word == '%':
            value = -0.20
        elif word == 'out':
            value = -0.30
    elif s and s[0].isalpha() and previous:
        strength = nasal_strength(previous) * consonant_strength(s)
        # Do not interpret the n in a textual newline escape as a nasal.
        if previous == 'n' and before.endswith('\\'):
            strength = 0.0
        strength *= CURRENT_LENGTH[min(len(s), 8) - 1]
        strength *= PREVIOUS_LENGTH[min(len(previous.strip()), 8) - 1]
        value = -strength
    return (doc, s, previous), float(value)

programs.luna:
"""A deliberately small sparse proxy: give a slight negative score to the
common English token 'of' and a smaller one to other non-ASCII letters."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token.strip().lower() == "of":
        return None, -0.03
    if any(ord(ch) > 127 and ch.isalpha() for ch in token):
        return None, -0.01
    return None, 0.0

programs.sol:
"""Negative lexical responses centered on speaking and lecturing.

The largest pulses are for 讲/講, followed by ``speaker`` and a small speech
vocabulary.  Lowercase ``speaker`` is stronger after ``the``, especially early
in a document.  Seeing kana selects a weaker Japanese setting for 講.  Listed
Chinese compound endings receive smaller pulses after 讲/講.  The ambiguous
Korean syllable 강 also triggers without checking its meaning.

Document endings get a negative pulse; message and thinking endings get small
positive pulses.  Everything else is zero.  State resets at document changes.
This approximates the lexical core, not the weaker idiosyncratic responses.
"""
import math

READS = ()

SPEECH_WORDS = {
    'speaker': -1.85,
    'speakers': -1.35,
    'talk': -0.65,
    'talks': -0.70,
    'talking': -0.78,
    'talked': -0.80,
    'speak': -0.42,
    'speaks': -0.36,
    'speaking': -0.54,
    'spoken': -0.26,
    'speech': -0.18,
    'lecture': -0.75,
    'lectures': -0.85,
    'lecturer': -0.60,
    'listener': -0.40,
    'presenter': -0.50,
    'narrator': -0.56,
    'deliver': -0.30,
    'delivered': -0.27,
    'delivering': -0.33,
    'delivery': -0.22,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, japanese = 0, '', False
    else:
        _, position, previous, japanese = carry
        position += 1
    japanese = japanese or any(
        '\u3041' <= c <= '\u3096' or '\u30a1' <= c <= '\u30fa'
        for c in token
    )
    if token == '<|endoftext|>':
        value = -0.74
    elif token == '<|im_end|>':
        value = 0.06
    elif token == '</think>':
        value = 0.14
    elif word == '讲':
        value = -5.3
    elif word == '講':
        value = -4.35 if japanese else -5.15
    elif word in {'讲师', '来讲', '宣讲', '讲课'}:
        value = -3.1
    elif word == '讲述':
        value = -2.3
    elif '讲' in word or '講' in word:
        value = -1.6
    elif word == '강':
        value = -1.95
    elif word in {'说', '說', '谈', '談', '说话', '发言'}:
        value = -0.32
    elif word in {'主播', '而言', '来说'}:
        value = -0.55
    elif word in {'говор', 'рассказ', 'рассказал'}:
        value = -0.45
    else:
        value = SPEECH_WORDS.get(word.lower(), 0.0)
        if word in {'Speaker', 'Speakers'}:
            value = -1.55
        elif word == 'Listener' or word.lower() == '.listener':
            value = -0.60
        elif word == 'speaker':
            if previous.strip().lower() == 'the':
                value = -2.12 + 0.07 * math.log1p(min(position, 128))
            elif token.startswith(' '):
                value = -1.53
            else:
                value = -1.25
        elif word.lower() == 'listeners':
            value = -0.30

    if previous.strip() in {'讲', '講'}:
        if word == '了':
            value = -1.35
        elif word in {'师', '師', '义', '義', '授'}:
            value = -0.82
        elif word in {'座', '談', '演', '台', '者', '坛'}:
            value = -0.50
    return (doc, position, token, japanese), float(value)

programs.haiku:
"""Speech-word detector (negative sign).

The component goes strongly negative on tokens that name a speaker or a talk:
"speaker" (about -1.8), the Chinese 讲/講 ("lecture, speak", about -5) and 讲师
("lecturer", about -3); more weakly on the verbs and nouns of giving a talk
("talk", "talking", "lecture", "listener", about -0.6 to -0.8) and "speak"-type
words (about -0.3 to -0.5). It also goes about -0.74 on the end-of-document token.
Everywhere else it is near zero.
"""
READS = ()

SPEAKER = {"speaker", "speakers", "presenter", "narrator", "lecturer"}
TALK = {"talk", "talks", "talking", "talked", "lecture", "lectures", "listener", "preach"}
SPEAK = {"speak", "speaking", "speaks", "spoke", "spoken", "speech", "deliver", "delivered",
         "delivery", "说", "谈", "言", "发言", "说话"}
CHINESE_LECTURE = {"讲": -5.0, "講": -4.5, "讲师": -3.0, "演讲": -1.6, "讲话": -1.5,
                   "讲故事": -1.3, "讲述了": -1.7, "主播": -0.6}
END = "<|endoftext|>"


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip().lower()
    if s in CHINESE_LECTURE:
        v = CHINESE_LECTURE[s]
    elif s in SPEAKER:
        v = -1.8
    elif s in TALK:
        v = -0.7
    elif s in SPEAK:
        v = -0.4
    elif s == END:
        v = -0.74
    else:
        v = 0.0
    return carry, v

programs.luna:
"""Marks document endings and a few words about spoken communication."""

