SPEECH_WORDS = {"talk", "talking", "lecture", "lectures", "speaker"}


def step(carry, prefix, upstream):
    """Predict a negative activation on end markers and speech-related words."""
    token = prefix.token_strings[-1].strip().casefold()
    if token == "<|endoftext|>" or token in SPEECH_WORDS:
        return None, -0.80
    return None, -0.00214

programs.haiku:
"""Negation / prohibition detector for layer-0 MLP component 2787.

It fires on the token that negates or forbids an action: English "not" and the
clitic "n't" (after "do", "is", "can", ...), "don", "cannot", "never", the
Chinese prohibitions 不要 / 別 / 不能, French "pas", German "nicht", Russian "не".
Strength: "don't" and Chinese prohibitions are strongest; plain "not" is medium.
Everywhere else it is near zero.
"""

READS = ()

VALUE = {}
for t in (" not", "not", " Not", "Not", " NOT", "NOT"):
    VALUE[t] = 1.0
for t in ("'t", "’t", "'T", " dont"):
    VALUE[t] = 1.2
for t in (" don", "don", " Don", "Don"):
    VALUE[t] = 0.9
for t in (" never", " Never", "never", " cannot", " Nor", " nor"):
    VALUE[t] = 0.6
for t in ("不要", "別", "不能", "不得"):
    VALUE[t] = 1.5
for t in (" не", "Не", " nicht", " pas", " nie", "不", "不是"):
    VALUE[t] = 0.4


def step(carry, prefix, upstream):
    return carry, VALUE.get(prefix.token_strings[-1], 0.0)

programs.luna:
"""Approximate the component's sparse response to negation and requests.

It is strongest on the token “not” and English n't endings; it also gives
smaller responses to contraction stems and other negative words. “Please”
and a few request words are another weaker, related cue.
"""
READS = ()

NEGATIVE_WORDS = frozenset({
    "never", "nor", "ne", "pas", "не", "нет", "nicht", "cannot",
    "cant", "dont",
})
CONTRACTION_STEMS = frozenset({
    "don", "doesn", "didn", "isn", "aren", "wasn", "weren",
    "shouldn", "wouldn", "couldn", "mustn",
})
REQUEST_WORDS = frozenset({"please", "請", "请", "ください", "してください"})


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word == "not":
        return None, 1.04
    if word.endswith("n't") or word in {"'t", "’t"}:
        return None, 1.09
    if word in CONTRACTION_STEMS:
        return None, 0.47
    if word in REQUEST_WORDS:
        return None, 0.81
    if word in NEGATIVE_WORDS:
        return None, 0.19
    return None, 0.0

programs.sol:
"""Approximate a contracted-auxiliary response from token text.

Pronoun + contraction is strongest, ordinary possessive 's is weaker, and
let's is intermediate. Curly apostrophes strengthen contractions. Smaller
rules cover full forms of 'be', 'let me', negation, French elision, a few
other copulas, and escaped/split apostrophes. Most tokens predict zero.
Only the preceding token is retained, reset at each document boundary.
"""
import re

READS = ()
S_AUXILIARY = {
    'it': 7.4, 'he': 8.3, 'she': 8.2, 'what': 8.0, 'who': 7.4,
    'there': 8.1, 'that': 6.8, 'here': 5.1, 'where': 5.6, 'how': 5.7,
}
PRONOUNS = {'i', 'you', 'we', 'they', 'he', 'she', 'it', 'who', 'there', 'that'}
BE = {'is': 0.8, 'are': 0.90, 'was': 0.90, 'were': 0.98, 'am': 0.1}
MODALS = {'would', 'could', 'should', 'might', 'must', 'will', 'shall'}
NEGATED_STEMS = {
    'don', 'doesn', 'didn', 'can', 'won', 'isn', 'aren', 'wasn', 'weren',
    'haven', 'hasn', 'hadn', 'ain', 'couldn', 'wouldn', 'shouldn', 'n',
}
NEGATED_AUXILIARIES = set(BE) | MODALS | {'do', 'does', 'did', 'has', 'have', 'had'}
ENDINGS = {'re': 7.5, 'm': 7.0, 've': 6.1, 'd': 4.9, 'll': 4.8}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    match = re.search(r'([A-Za-z]+)$', prev)
    raw = match.group(1) if match else ''
    word = raw.lower()
    normal = token.replace('’', "'").replace('`', "'").lower()
    curved = '’' in token
    value = 0.0
    if normal == "'s":
        value = S_AUXILIARY.get(word, 1.0)
        if curved and word in S_AUXILIARY:
            value += 0.5
        if word == 'let':
            value = 3.65
        elif word in {'men', 'women', 'children', 'people'}:
            value = 0.4
    elif normal[0:1] == "'" and normal[1:] in ENDINGS:
        ending = normal[1:]
        if word in PRONOUNS:
            value = ENDINGS[ending] + 0.5 * (word == 'we')
            value += (0.85 if ending == 'm' else 0.5) * curved
            if prev == 'I':
                value -= 0.4
            if raw == 'i':
                value -= 1.7
        elif ending == 've' and word in MODALS:
            value = 2.1
        else:
            value = 1.5 if not prev else 0.3
    elif normal == "'t":
        value = 1.6 + 0.1 * curved
        if word in {'isn', 'aren', 'wasn', 'weren'}:
            value += 0.25
        elif word in {'couldn', 'wouldn', 'shouldn'}:
            value -= 0.4
        if word not in NEGATED_STEMS:
            value = 0.1
    elif normal in {"'il", "'elle", "'est", "'on", "'à", "'en"}:
        value = 0.8
    elif token == ';s':
        value = 1.3  # HTML-escaped possessive
    elif token == "\\'" and word in PRONOUNS:
        value = 2.8
    elif token in {'s', 're', 'm', 've'} and prev.endswith(("'", '’', '´')):
        value = 2.4 if prev.startswith('\\') else 1.1
    else:
        text = token.lstrip(' \t\r\n._/(-').lower()
        boundary = token.lower() != text or not prev or not prev[-1:].isalnum()
        if boundary:
            if text in BE:
                value = BE[text]
                if text == 'am':
                    value = 1.9 if raw == 'I' else 1.1 if raw == 'i' else 0.1
                elif text in {'are', 'were'} and word in {'you', 'we', 'they'}:
                    value = 1.5
                elif text in {'is', 'was'} and word in {'he', 'she'}:
                    value += 0.35
                elif text == 'was' and word in {'i', 'it'}:
                    value += 0.3
                if raw[:1].isupper() and raw != 'I' and word in PRONOUNS:
                    value -= 0.15
            elif text == 'me':
                value = 0.98 if word == 'let' else 0.07
            elif text == 'not':
                value = -0.1 if word in NEGATED_AUXILIARIES else 0.4
                if word in {'may', 'might'}:
                    value = 0.34
                if prev.replace('’', "'") in {"'s", "'re", "'m"}:
                    value = 0.65
            elif text == 'be':
                adjustments = {'to': 0.11, 'can': -0.22, 'may': 0.27, 'might': 0.36}
                value = adjustments.get(word, 0.0)
            elif text == 'been':
                value = -0.13
            elif text in {'est', 'es', 'é', 'è', 'está', 'です'}:
                value = 0.35
    if token.startswith('`'):
        value *= 0.6
    return (doc, token), float(value)

programs.haiku:
"""Layer-0 MLP output feature 2788: a "be" verb (is / are / 's / 're ...) right after a subject.

The feature switches on at the verb that says what a subject is, or is doing, when that verb
is a copula or auxiliary: "is", "are", "was", "were", "am", or a short form written onto
the subject ("it's", "you're", "I'm", "we've", "they'll", "I'd", "isn't").

  * Short forms are the strongest: 're and 'm about 7-8; 's standing for "is" after a
    pronoun or "there/that/what" about 7.5, after "here" about 5; 've after a pronoun
    about 6; 'd after a pronoun about 4.5; 'll about 5; n't about 1.6.
  * "'s" after "let" (let's) is moderate, about 3.6. "'s" marking a possessive (John's) is
    weak, about 0.9.
  * The full words are weak to moderate: "is", "are", "was", "were" about 1; "am" after "I"
    about 2; "me" after "let" about 1.
  * Silent on "be", "been", "has", "have", "will", "can", "not" and most other tokens.

The activation depends only on the current token and the word before it.
"""

READS = ()

# Words that take a short form as its subject: "it's", "there's", "I've", "who'd".
PRONOUN = {"i", "you", "we", "they", "he", "she", "it", "who", "that", "what", "there"}
IS_SUBJECT = {"it", "that", "there", "what", "he", "she", "here", "where", "who", "this"}
WORD = {"is": 0.8, "are": 1.0, "was": 0.9, "were": 1.0}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].replace("’", "'")
    prev = ""
    if len(prefix) > 1:
        prev = prefix.token_strings[-2].replace("’", "'").strip().strip("\"'“”(").lower()
    if raw in ("'re", "'m", "'ll", "'t", "'ve", "'d", "'s"):
        if raw == "'re":
            return carry, 8.0
        if raw == "'m":
            return carry, 7.5
        if raw == "'ll":
            return carry, 5.0
        if raw == "'t":
            return carry, 1.6
        if raw == "'ve":
            return carry, 6.0 if prev in PRONOUN else 1.5
        if raw == "'d":
            return carry, 4.5 if prev in PRONOUN else 0.0
        if prev in IS_SUBJECT:
            return carry, 5.2 if prev == "here" else 7.5
        if prev == "let":
            return carry, 3.6
        return carry, 0.9
    word = raw.strip()
    if word == "am":
        return carry, 2.0 if prev == "i" else 0.1
    if word == "me" and prev == "let":
        return carry, 1.0
    if raw[:1] == " " and word in WORD:
        return carry, WORD[word]
    return carry, 0.0

programs.luna:
"""Recognize a few English auxiliary endings and the clearest 'be' tokens.

The strong signal is not possessive -s: it is an apostrophe ending a spoken
contraction. A preceding pronoun or existential/wh word makes -'s much more
likely to be "is/has" than possession.
"""

READS = ()

PRONOUNS = {"he", "she", "it", "that", "who", "what", "there"}
WH_WORDS = {"who", "what", "where", "when", "why", "how"}

CONTRACTIONS = {
    "'re": 7.5, "’re": 8.0,
    "'ve": 6.0, "’ve": 6.1,
    "'m": 6.7, "’m": 8.0,
    "'ll": 4.8, "’ll": 5.4,
    "'d": 4.6, "’d": 4.7,
    "'t": 1.6, "’t": 1.7,
}

BE_FORMS = {
    " is": 0.81, " are": 0.96, " was": 0.95, " were": 1.06,
    " am": 1.3,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = ""
    if len(prefix.token_strings) > 1 and (
        prefix.document_ids[-1] == prefix.document_ids[-2]
    ):
        previous = prefix.token_strings[-2].strip().lower()

    if token in ("'s", "’s"):
        if previous in {"let", "let's", "let’s"}:
            return None, 3.6
        if previous in {"here"}:
            return None, 5.4
        if previous in PRONOUNS or previous in WH_WORDS:
            return None, 8.0 if token == "’s" else 7.8
        return None, 0.85

    if token in CONTRACTIONS:
        return None, CONTRACTIONS[token]

    if token in BE_FORMS:
        if token == " am" and previous == "i":
            return None, 1.65
        return None, BE_FORMS[token]

    return None, 0.0

