"""Approximate the strong negative response to expressive punctuation.

Attached ellipses dominate, particularly after an ASCII word. Spaced
ellipses, path syntax, and long decorative runs are weaker. Questions and
exclamations also respond, less so with quotes or bundled line breaks.
Other text is left at zero rather than fitting small lexical variations.
"""
import re

READS = ()
ELLIPSIS = re.compile(r'[.…]{2,}|…|。{2,}|・{2,}')
QUOTES = '\"\'”’」'


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    text = raw.strip().replace('？', '?').replace('！', '!')
    same = prefix.position > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]
    previous = prefix.token_strings[-2] if same else ''
    last = previous[-1:]
    spaced, lines = raw[:1].isspace(), raw.count('\n')
    dots = ELLIPSIS.search(text)
    value = 0.0
    if dots and not any(c.isalnum() for c in text[:dots.start()]) and '/' not in text:
        run = dots.group()
        n = run.count('.') + 3 * run.count('…')
        if spaced:
            value = -0.25 if n == 2 or n > 3 else -0.05
        else:
            strength = 1.3 if n == 2 else 6.0 / max(2, n - 1)
            if run == '…':
                strength = 2.6
            elif run[0] in '。・':
                strength = 1.2
            weight = 0.65 if not last else 0.40
            if last.isspace():
                weight = 0.12
            elif last.isdigit() or (last.isalpha() and not last.isascii()):
                weight = 0.70
            elif last.isalpha():
                weight = 1.0 if previous.startswith(' ') else 0.90
            if lines:
                weight = max(weight, 0.65) if weight > 0.2 else 0.30
                strength *= 0.55
            before, after = text[:dots.start()], text[dots.end():]
            if before or (after and not after[0].isalpha()):
                strength *= 0.50
            value = -strength * weight
    elif text and not any(c.isalnum() for c in text) and '=' not in text:
        if '?' in text:
            suffix = text[text.rfind('?') + 1:]
            strength = 0.74 if text.count('?') == 1 else 1.0
            if suffix:
                strength *= 0.34 if any(c in suffix for c in QUOTES) else 0.50
            if lines:
                strength *= 0.30 if lines > 1 else 0.41
            elif spaced:
                strength *= 0.85 if text.count('?') == 1 else 0.25
            value = -strength * (0.70 if last.isspace() else 1.0)
        elif '!' in text:
            strength = 0.48 if text.count('!') == 1 else 0.90
            if text.strip('!'):
                strength *= 0.60 if text.endswith(',') else 0.26
            elif lines:
                strength *= 0.35
            elif spaced:
                strength *= 0.48
            weight = 0.25 if last.isspace() else (
                0.57 if last and not last.isalpha() else 1.0)
            value = -strength * weight
    return None, float(value)

