"""Estimate the layer's rare negative response to question, exclamation, and ellipsis marks.

The response is strongest on a bare mark; tokens that also end the line have a
smaller response. Ordinary commas and periods are left alone.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip(" ")
    breaks = token.count("\n")
    mark = token.rstrip("\n")

    if mark and set(mark) == {"?"}:
        return None, (-0.75 if breaks == 0 else -0.34 if breaks == 1 else -0.24)
    if mark and set(mark) == {"!"}:
        return None, (-0.51 if breaks == 0 else -0.15 if breaks == 1 else -0.20)

    if "…" in mark:
        value = -0.78 if mark.count("…") > 1 else -2.28
        if "," in mark:
            value = -1.99
        if breaks:
            value *= 0.45
        return None, value

    if mark and set(mark) == {"."}:
        if len(mark) == 2:
            value = -1.49
        elif len(mark) >= 3:
            value = -2.84
        else:
            return None, 0.0
        if breaks == 1:
            value = -1.10
        elif breaks > 1:
            value = -0.95
        return None, value

    return None, 0.0

