"""Document opening tokens and consonant-cluster word completions.

At a document boundary, predict a positive activation, strongest for headings,
code preambles and common sentence openers. Within documents, predict a
negative activation for short vowel-led fragments immediately after an English
consonant onset (for example, 'Sh' followed by 'ag'). Longer fragments have a
weaker response. These are coarse lexical/orthographic rules: they leave most
positions near zero and do not reproduce every token's individual response.
"""
import re

READS = ()
ONSETS = frozenset('''bl br ch cl cr dr fl fr gl gr ph pl pr sc sh sk sl sm
sn sp st sw th tr tw wh wr qu squ sch scr shr spl spr str thr'''.split())
VOWELS = frozenset('aeiouy')
ARTICLES = frozenset(('A', 'An'))
OPENING_PRONOUNS = frozenset(('I', 'We', 'You', 'It'))
CONNECTORS = frozenset('On As At By For From With To When While'.split())


def opening(token):
    # Headings and source-file preambles.
    if token == 'Title':
        return 4.39
    if token == '##':
        return 2.94
    if token in ('#', 'import', 'package'):
        return 2.50
    if token.startswith(('#', '/*')) or token in ('from', 'export'):
        return 1.75
    if token.startswith('//'):
        return 1.35
    if token.startswith(('<?', '"""')):
        return 1.55
    if token in ('using', 'def', 'class', 'public'):
        return 1.10
    if token == '<|im_start|>':
        return 0.75
    # Familiar sentence-opening words, rather than a token-ID lookup.
    if token == 'The':
        return 2.08
    if token == 'This':
        return 1.75
    if token == 'What':
        return 2.74
    if token == 'How':
        return 2.12
    if token in ARTICLES or token in OPENING_PRONOUNS:
        return 1.35
    if token in ('In', 'If'):
        return 1.50
    if token in ('Why', 'Which', 'Where', 'Who', 'Is', 'Are', 'Can'):
        return 1.30
    if token in CONNECTORS:
        return 0.85
    if token.lower() in ONSETS:
        return 1.25
    # General orthographic classes for other opening tokens.
    if token[:1].isspace():
        return 0.23
    if not token.isascii():
        return 0.22
    if token.isdigit():
        return 0.18
    if token.isalpha():
        return 0.71 if token[0].isupper() else 0.48
    return 0.31


def completion(previous, token):
    match = re.search(r'[A-Za-z]+$', previous)
    onset = match.group().lower() if match else ''
    if onset not in ONSETS or not token.isascii() or not token.isalpha():
        return -0.002
    text = token.lower()
    word_start = previous[:1].isspace()
    if text[0] in VOWELS:
        if len(text) == 1:
            return 0.0
        if len(text) <= 3:
            return -0.37 if word_start else -0.20
        if len(text) == 4:
            return -0.23 if word_start else -0.09
        return -0.13 if word_start else 0.0
    return 0.10


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        position, value = 0, opening(token)
    else:
        position = carry[2] + 1
        value = completion(carry[1], token)
        # A small positive tail in the first few document positions.
        if position == 1:
            value += 0.05
        elif position < 4:
            value += 0.01
    return (document, token, position), float(value)

"""Estimate an opening-group signal from token punctuation.

Square brackets and curly braces usually give positive pulses. Empty pairs,
quotes, whitespace and trailing newlines distinguish indexing/citations,
JSON-like objects, TeX groups and code-block openers. A preceding condition
parenthesis weakens a brace; a preceding identifier strengthens a typed
literal. TeX subscripts and comparison operators can give negative pulses.

Only the previous token is remembered, resetting at row/document boundaries.
An initial brace gets an especially strong pulse. Other lexical effects are
left at zero rather than represented by a large token lookup table.
"""
READS = ()


def activation(s, previous):
    t, p = s.strip(), previous.strip()
    spaced = s[:1].isspace()
    if '!=' in t:
        return -1.43 if spaced else -1.1
    if t == '≠':
        return -0.45
    if t in ('<=', '>='):
        return -0.35
    if t in ('===', '==') and spaced:
        return -0.27 if t == '===' else -0.11
    if t in ('【', '［'):
        return 0.72
    if ')(' in t:
        return 0.53
    if '{' in t:
        before, after = t.rsplit('{', 1)
        if before.endswith('_'):
            return -0.5 if '}' in before or p in ('sum', 'int', 'lim') else -0.1
        if before.endswith('^'):
            return 0.71 if after.startswith('-') else 0.37
        if '}' in after:
            return 0.18
        if not before:
            if '\n' in s:
                # Blocks after a condition differ from typed object literals.
                if p.endswith((')', '=>')):
                    return -0.14 if spaced else 0.05
                if p in ('else', 'try', 'finally', 'do', 'struct', 'interface'):
                    return 0.09 if spaced else 0.32
                if p[-1:].isalpha():
                    return 0.27 if spaced else 0.98
                if p.endswith((':', '=', ',')):
                    return 0.46 if spaced else 0.63
                return 0.07 if spaced else 0.21
            if after.startswith(('"', "'")):
                return 0.7 if spaced else 0.8
            if after.startswith('\\'):
                value = 0.8 if spaced else 1.31
                return value - 0.35 if p.endswith('^') else value
            if not after:
                if p.endswith((')', '=>')):
                    return 0.35
                if not spaced:
                    return 1.65
                return 1.2 if p[-1:].isalpha() else 0.98
            return 1.05 if spaced else 1.2
        if set(before) <= set('{}'):
            return 1.05
        if before.endswith(']'):
            return 1.55
        if before.endswith('$'):
            return 0.95 if spaced else 0.73
        if before.endswith(')'):
            return 0.1 if '\n' in s else 1.05
        return 0.3 if '\n' in s else 0.55
    if '[' in t:
        before, after = t.rsplit('[', 1)
        if ']' in after:
            return -0.04
        if before.endswith('\\') or p.endswith('\\'):
            return 0.25
        if before.endswith((']', ')', '}')):
            return 0.85
        if before and before != '[':
            return 0.45
        if '\n' in s:
            return 0.36
        if not after:
            if spaced:
                return 0.56 if any(c in p for c in "\"'[]") else 0.96
            return 0.46 if ']' in p else 0.78
        return 0.85 if after.isalpha() else 0.65
    return {'_\\': -0.81, '^\\': -0.38, '}_': -0.42}.get(t, 0.0)


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    new_document = carry is None or carry[0] != doc
    previous = '' if new_document else carry[1]
    value = activation(s, previous)
    if new_document and s.strip().startswith('{'):
        value = 0.9 if '\n' in s else (7.7 if s == '{' else 2.3)
    return (doc, s), value

