"""Layer 0, MLP down-projection, component 2802: an "opening bracket" detector.

What it does: it reads the newest token's text and switches on when that token opens
a bracket or brace group. The bare "{" is strongest (1.6); other tokens that end in
"{", or that contain "{" or "[" and continue into a group, are weaker (about 1.0 and 0.8).
Examples: " {", " [", "{\\", "{\"", "}{", "][", "[". It stays off for empty pairs ("{}",
"[]") and is slightly negative for LaTeX subscripts and superscripts ("_{", "^{").
Tokens that close a line on an opening brace (" {\\n") are near 0, while "{\\n" is weak.
Two kinds of token push it negative: "!=" (-1.4) and a few Chinese words that mean
"different", "each", "specific" or "based on" (-1.0).

Stateless: the value depends only on the newest token, not on earlier tokens.
"""

READS = ()

CHINESE_DISTINCTION = ("不同", "各", "同一", "基于", "特定", "针对")


def activation(tok):
    if "!=" in tok:
        return -1.4
    if any(word in tok for word in CHINESE_DISTINCTION):
        return -1.0
    if "_{" in tok:
        return -0.3
    if "^{" in tok:
        return 0.4
    if tok == "{\n" or tok == "{\r\n":
        return 0.3
    if "{" not in tok and "[" not in tok:
        return 0.0
    if tok.endswith(("\n", "\r")) or "[]" in tok or "{}" in tok:
        return 0.0
    if tok == "{":
        return 1.6
    if "}" in tok or "]" in tok or tok.endswith("{"):
        return 1.0
    return 0.8


def step(carry, prefix, upstream):
    return None, float(activation(prefix.token_strings[-1]))

