"""Predict a response to opening square and curly delimiters.

The component most often adds a positive signal when text opens a bracketed
list, object, or mathematical group. Curly braces used for subscripts are a
small exception; ordinary punctuation and text receive no signal.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix) > 1 else ""

    if "_{" in token:
        return None, -0.5
    if "^{" in token:
        return None, 0.35
    if "{" in token:
        if "\n" in token and (previous.rstrip().endswith(")") or previous.strip() == "else"):
            return None, 0.0
