    # varies with context, so use a conservative typical value.
    if stripped.startswith("##"):
        return None, 0.12
    if stripped and stripped[-1] == "!":
        return None, 0.124
    if stripped and stripped[-1] == ".":
        return None, 0.054
    if stripped and stripped[-1] == "?":
        return None, 0.030

