    word = token.strip().lower()
    if not token[:1].isspace() and word in WITH_ENDINGS:
        return -3.6
    if word in {'respect', 'regards'}:
        return -4.75
    if word == 'regard':
        return -3.8
    if word == 'reference':
        return -1.75
    if word == 'no':
        return -3.25
    if word in {'all', 'each', 'every'}:
        return -2.5
    if word in {'only', 'just'}:
        return -2.2
    if word in {'ease', 'open', 'care', 'caution'}:
        return -2.4
    if word in {'us', 'which', 'whom', 'other', 'others', 'same', 'its'}:
        return -1.55
    if word == 'their':
        return -1.3
    if word in QUANTITY or word in PRONOUNS or word in QUALITIES:
        return -0.95
    if word in {'the', 'our', 'different'}:
        return -0.63
    if word in {'this', 'these', 'those', 'my'}:
        return -0.3
    if word in {'a', 'an'} or word in NUMBER_WORDS or word.isdigit():
        return -0.05
    if word == 'exit':
        return -0.4
    if word == 'great':
        return -1.7
    if not token.strip():
        return -0.24
    if not token[:1].isspace() and word.isalpha():
        return -0.65
