    if stripped == '問' and previous.endswith(('質', '訪')):
        value = 3.00
    if word == 'know' and token.startswith(' '):
        if before == 'to':
            value = 0.75
        elif before in {"'t", '’t', "n't", 'not', 'never', 'dont', 'should'}:
            value = 0.62
        elif before in {'i', 'we', 'you', 'they', 'all'}:
            value = 0.20
    if word in {'said', 'says'} and token.startswith(' '):
        if quote_age <= 2:
            value = -0.15 if word == 'said' else 0.02
        elif word == 'said':
            if before in {'be', 'is', 'are', 'was', 'being', 'it'}:
                value = 0.48
            elif before in {'i', 'we', 'you', 'they', 'he', 'she'}:
                value = 0.33
        elif before in {'problem', 'question', 'it'}:
            value = 0.90
    if before in ASK and word in ASK_ECHO:
        value = ASK_ECHO[word]
    if token == '\n' and previous == 'user':
        value = 0.085
    if stripped == 'Q':
        value = 0.81 if not previous or previous == '<|endoftext|>' else 0.27
    if token in MARKUP:
        value = MARKUP[token]
    if stripped == '¿':
        value = 0.53
    if stripped.endswith((
        ',"', '."', '!"', '?"', ',”', '.”', '!”', '?”',
    )):
        quote_age = 0
    return (doc, token, quote_age), float(value)

programs.haiku:
"""Ask-detector. The component fires on words meaning "to ask": the verbs ask / asked /
asking / asks / inquire, and the Chinese and Japanese characters 问 and 問 (and compounds
such as 询问 and 咨询). It fires more weakly on words about questions and wondering
(question, query, wonder, 问题), and more weakly still on speech verbs (say, said, tell,
说). Everything else is zero. The value is a fixed strength per word class: whole-word
verbs (leading space) fire harder than the same letters inside a longer word. Only the
current token is read.
"""

READS = ()

ASK_CHARS = {"问", "問"}                     # "ask", in Chinese / Japanese
ASK_VERBS = {"ask", "asks", "asked", "asking", "inquire", "inquired", "inquiry", "enquiries"}
ASK_COMPOUNDS = {"询问", "詢問", "咨询", "諮詢", "问答", "請問", "请问", "问我", "问他", "询"}
POLITE_ASK = {"请", "請", "문"}              # "please", "inquiry" (Korean 문의)
QUESTION_WORDS = {"question", "questions", "q", "query", "queries", "prompt", "problem",
                  "questioned", "questioning", "вопрос", "вопросы", "рос", "frage", "问题",
                  "問題", "的问题", "疑问"}
WONDER_WORDS = {"wonder", "wonders", "wondered", "wondering", "curious", "curiosity"}
SAY_WORDS = {"says", "say", "said", "saying", "tell", "told", "知", "说", "說", "曰", "道"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    if word in ASK_CHARS:
        value = 6.5
    elif word in ASK_VERBS:
        value = 3.4 if raw[:1] == " " else 1.5
    elif word in ASK_COMPOUNDS:
        value = 4.0
    elif word in POLITE_ASK:
        value = 1.0
    elif word in WONDER_WORDS:
        value = 1.7
    elif word in QUESTION_WORDS:
        value = 0.5
    elif word in SAY_WORDS:
        value = 0.4
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Approximate a spatial-phrase signal with ordinary word classes.

Route words and “on” get small positive responses; articles get a small baseline
that is raised after a spatial preposition. Other tokens are left at zero.
"""

READS = ()

ROUTE_WORDS = frozenset({
    "up", "down", "over", "across", "along", "through", "out", "off",
})
ARTICLE_PREPOSITIONS = frozenset({
    "at", "on", "over", "across", "under", "along", "below", "through",
    "up", "off", "down", "above",
})


def _surface(piece):
    return piece.strip().lstrip("-").casefold()


def step(carry, prefix, upstream):
    current = prefix.token_strings[-1]
    word = _surface(current)
    doc = prefix.document_ids[-1]
    previous = ""
    if carry is not None:
        old_doc, old_piece = carry
        if old_doc == doc:
            previous = _surface(old_piece)

    value = 0.0
    if word in ROUTE_WORDS:
        value = 0.55
    elif word == "on":
        value = 0.22
    elif word in {"the", "a", "an"}:
        value = 0.10 if word == "the" else 0.04
        if previous in ARTICLE_PREPOSITIONS:
            value = 0.90 if word == "the" else 0.70

    return (doc, current), float(value)
